  janitor::adorn_totals("row") |&gt;
  janitor::adorn_percentages("all") |&gt;
  janitor::adorn_pct_formatting()







NotaNota



Estos tabulados son útiles para “tener una idea”, pero si vas a reportar precisión (IC, CV), necesitas el diseño con {srvyr}.

9 5. Estimaciones con diseño: medias, proporciones y totales

9.1 5.1 Media ponderada (con error estándar e IC)

diseno |&gt;
  summarise(
    media_ing = survey_mean(ing_cor, na.rm = TRUE, vartype = c("se", "ci"))
  )



9.2 5.2 Proporción ponderada (binaria)
Ejemplo: define una variable binaria (ajusta a tus variables reales).

diseno2 &lt;- diseno |&gt;
  mutate(es_urbano = tam_loc == 1)

diseno2 |&gt;
  summarise(
    prop_urbano = survey_mean(es_urbano, na.rm = TRUE, vartype = c("se", "ci"))
  )



9.3 5.3 Totales ponderados

diseno |&gt;
  summarise(total_hogares = survey_total(1, vartype = c("se", "ci")))

10 6. Tabulados ponderados por grupos (con diseño y varianza)
Ejemplo: media de ingreso por tamaño de localidad.

tab_ing &lt;- diseno |&gt;
  group_by(tam_loc) |&gt;
  summarise(
    n_muestral = unweighted(n()),
    media_ing = survey_mean(ing_cor, na.rm = TRUE, vartype = c("se", "ci"))
  )

tab_ing

Tabla bonita:

tab_ing |&gt;
  gt::gt() |&gt;
  gt::fmt_number(columns = where(is.numeric), decimals = 2) |&gt;
  gt::tab_header(title = "Media ponderada de ingreso por grupo (con SE e IC)")

12 8. Comparación ponderado vs. no ponderado (misma tabla)

no_pond &lt;- concentrado |&gt;
  group_by(tam_loc) |&gt;
  summarise(
    n = n(),
    media_ing_no = mean(ing_cor, na.rm = TRUE),
    .groups = "drop"
  )

pond &lt;- diseno |&gt;
  group_by(tam_loc) |&gt;
  summarise(
    n_muestral = unweighted(n()),
    media_ing = survey_mean(ing_cor, na.rm = TRUE, vartype = c("se", "ci"))
  ) |&gt;
  transmute(
    tam_loc,
    media_ing_pond = media_ing,
    se = media_ing_se,
    ci_low = media_ing_low,
    ci_high = media_ing_upp
  )

comparativa &lt;- no_pond |&gt;
  left_join(pond, by = "tam_loc") |&gt;
  mutate(
    diferencia = media_ing_pond - media_ing_no
  )

comparativa

5 Tablas de frecuencia: R base vs. {janitor} vs. {dplyr}

5.1 Percepción general de seguridad en Morelia

5.1.1 R base: table() y prop.table()

# Frecuencias absolutas
table(morelia$seg_ciudad)

# Frecuencias relativas (proporciones)
prop.table(table(morelia$seg_ciudad))

# Porcentajes redondeados
round(prop.table(table(morelia$seg_ciudad)) * 100, 1)



5.1.2 {janitor}: tabyl() + adorn_*()
tabyl() produce frecuencias absolutas y relativas. Las funciones adorn_*() agregan totales, porcentajes con formato y etiquetas.

morelia |&gt;
  tabyl(seg_ciudad) |&gt;
  adorn_totals("row") |&gt;
  adorn_pct_formatting(digits = 1) |&gt;
  knitr::kable(
    caption   = "Percepción de seguridad en Morelia · ENSU T4 2025",
    col.names = c("Percepción", "n", "%")
  )







Nota¿Qué hace cada adorn_*()?




adorn_totals("row"): agrega una fila de totales.
adorn_percentages(): convierte frecuencias a proporciones (por defecto sobre el total de filas).
adorn_pct_formatting(digits = 1): da formato de porcentaje con un decimal.
adorn_ns(): muestra también los valores absolutos junto a los porcentajes.





5.1.3 {dplyr}: count() + mutate()

morelia |&gt;
  count(seg_ciudad, name = "n") |&gt;
  mutate(
    pct = round(n / sum(n) * 100, 1)
  ) |&gt;
  knitr::kable(
    caption  = "Percepción de seguridad en Morelia · ENSU T4 2025",
    col.names = c("Percepción", "n", "%")
  )

6 Percepción de seguridad por lugar

# Calle
morelia |&gt;
  tabyl(seg_calle) |&gt;
  adorn_totals("row") |&gt;
  adorn_pct_formatting(digits = 1) |&gt;
  knitr::kable(caption = "Percepción de seguridad: en la calle")

# Transporte público
morelia |&gt;
  tabyl(seg_transporte) |&gt;
  adorn_totals("row") |&gt;
  adorn_pct_formatting(digits = 1) |&gt;
  knitr::kable(caption = "Percepción de seguridad: en el transporte público")


6.1 Comparación en una sola tabla con pivot_longer()
Podemos comparar varios lugares y reestructurar a formato long.

morelia |&gt;
  select(seg_calle, seg_transporte) |&gt;
  pivot_longer(
    cols      = everything(),
    names_to  = "lugar",
    values_to = "percepcion"
  ) |&gt;
  mutate(
    lugar = recode(lugar,
      "seg_calle"      = "Calle",
      "seg_transporte" = "Transporte público"
    )
  ) |&gt;
  filter(!is.na(percepcion)) |&gt;
  count(lugar, percepcion) |&gt;
  group_by(lugar) |&gt;
  mutate(pct = round(n / sum(n) * 100, 1)) |&gt;
  ungroup() |&gt;
  pivot_wider(
    names_from  = percepcion,
    values_from = c(n, pct)
  ) |&gt;
  knitr::kable(caption = "Percepción de seguridad por lugar · Morelia · ENSU T4 2025")

7 Expectativa sobre la delincuencia

7.1 Tabla con frecuencias acumuladas
Para variables ordinales (como escalas de Likert), las frecuencias acumuladas ayudan a interpretar la distribución.

morelia |&gt;
  tabyl(expectativa) |&gt;
  adorn_totals("row") |&gt;
  adorn_pct_formatting(digits = 1) |&gt;
  knitr::kable(caption = "Expectativa sobre delincuencia en los próximos 12 meses · Morelia")


morelia |&gt;
  count(expectativa) |&gt;
  filter(!is.na(expectativa)) |&gt;
  mutate(
    pct     = round(n / sum(n) * 100, 1),
    pct_acum = cumsum(pct)
  ) |&gt;
  knitr::kable(
    caption   = "Expectativa sobre delincuencia — frecuencias acumuladas · Morelia",
    col.names = c("Expectativa", "n", "%", "% acumulado")
  )







Nota¿Cuándo usar frecuencias acumuladas?



Las frecuencias acumuladas son útiles en variables ordinales (donde el orden importa), como escalas de satisfacción, efectividad o confianza. Permiten responder preguntas como: ¿qué porcentaje considera que la situación mejorará o seguirá igual de bien?

8 Desempeño y confianza en autoridades

8.1 Comparación de efectividad entre autoridades

morelia |&gt;
  select(efect_mun, efect_estatal, efect_gn) |&gt;
  pivot_longer(
    cols      = everything(),
    names_to  = "autoridad",
    values_to = "efectividad"
  ) |&gt;
  mutate(
    autoridad = recode(autoridad,
      "efect_mun"     = "Policía Municipal",
      "efect_estatal" = "Policía Estatal",
      "efect_gn"      = "Guardia Nacional"
    )
  ) |&gt;
  filter(!is.na(efectividad)) |&gt;
  count(autoridad, efectividad) |&gt;
  group_by(autoridad) |&gt;
  mutate(pct = round(n / sum(n) * 100, 1)) |&gt;
  ungroup() |&gt;
  select(-n) |&gt;
  pivot_wider(names_from = efectividad, values_from = pct) |&gt;
  gt() |&gt;
  tab_header(
    title    = "Efectividad percibida de las autoridades de seguridad (%)",
    subtitle = "Morelia · ENSU T4 2025"
  ) |&gt;
  tab_spanner(
    label   = "Evaluación (%)",
    columns = c(`Poco/nada efectivo`, `Muy/algo efectivo`)
  ) |&gt;
  cols_label(autoridad = "Autoridad") |&gt;
  tab_source_note("Fuente: ENSU T4 2025, INEGI. Porcentajes sobre respuestas válidas.")



8.2 Comparación de confianza entre autoridades

morelia |&gt;
  select(conf_mun, conf_estatal, conf_gn) |&gt;
  pivot_longer(
    cols      = everything(),
    names_to  = "autoridad",
    values_to = "confianza"
  ) |&gt;
  mutate(
    autoridad = recode(autoridad,
      "conf_mun"     = "Policía Municipal",
      "conf_estatal" = "Policía Estatal",
      "conf_gn"      = "Guardia Nacional"
    )
  ) |&gt;
  filter(!is.na(confianza)) |&gt;
  count(autoridad, confianza) |&gt;
  group_by(autoridad) |&gt;
  mutate(pct = round(n / sum(n) * 100, 1)) |&gt;
  ungroup() |&gt;
  select(-n) |&gt;
  pivot_wider(names_from = confianza, values_from = pct) |&gt;
  gt() |&gt;
  tab_header(
    title    = "Confianza en las autoridades de seguridad (%)",
    subtitle = "Morelia · ENSU T4 2025"
  ) |&gt;
  tab_spanner(
    label   = "Nivel de confianza (%)",
    columns = c(`Algo/mucha desconfianza`, `Mucha/algo confianza`)
  ) |&gt;
  cols_label(autoridad = "Autoridad") |&gt;
  tab_source_note("Fuente: ENSU T4 2025, INEGI. Porcentajes sobre respuestas válidas.")

9 Ordenamiento de categorías con {forcats}
A veces es útil ordenar las categorías por frecuencia para facilitar la lectura.

9.1 fct_reorder(): ordenar por frecuencia

morelia |&gt;
  count(efect_mun) |&gt;
  filter(!is.na(efect_mun)) |&gt;
  mutate(
    efect_mun = fct_reorder(efect_mun, n, .desc = TRUE)
  ) |&gt;
  arrange(efect_mun) |&gt;
  knitr::kable(caption = "Efectividad Policía Municipal (ordenada por frecuencia)")



9.2 fct_lump(): colapsar categorías poco frecuentes
Cuando hay categorías con muy pocos casos, fct_lump() las agrupa en “Otro”.
Ejemplo con expectativa: conservar solo las 2 categorías más frecuentes.

morelia |&gt;
  mutate(
    expectativa_agrup = fct_lump(expectativa, n = 2, other_level = "Otras respuestas")
  ) |&gt;
  tabyl(expectativa_agrup) |&gt;
  adorn_totals("row") |&gt;
  adorn_pct_formatting(digits = 1) |&gt;
  knitr::kable(caption = "Expectativa sobre delincuencia (categorías agrupadas)")







Tipfct_lump() vs. fct_lump_prop()




fct_lump(n = 2): conserva las n categorías más frecuentes.
fct_lump_prop(prop = 0.05): conserva las categorías que superan el 5% del total. Ambas son útiles para limpiar tablas con muchas categorías residuales.

